from lesson_authoring import entry as E
B=[['希腊 bios（βίος）','生命、一生、生活方式'],['近代构词成分 bio-','生命；生物；与生物有关的']]
BG=[['希腊 bios + -graphia → 后期希腊 biographia','一生 + 书写 → 生平记述'],['学术拉丁 biographia → 英语 biography','传记；传记写作']]
BC=B+[['英语 bio- + chemistry → biochemistry','生命中的化学 → 生物化学']]
def H(chain,label,meaning):return chain+[[label,meaning]]
WA=[
E('biography','英 /baɪˈɒɡrəfi/；美 /baɪˈɑːɡrəfi/','传记；生平记述','把一个人怎样走过一生，整理成有依据的故事。','bio-“一生” + -graphy“书写”；英语借入学术拉丁 biographia，背后是后期希腊语的组合。',BG,'a biography of someone 讲某人的经历、选择和所处时代。它可以是一整本书，也可以是简短生平。写得像故事不代表可以随便编；传记的核心仍是真实人物与可考的经历。','write a biography of；a biography of the scientist；an authorized biography。','biography 一般由别人写某人的生平；autobiography 是本人写自传。memoir 常围绕记忆中的某段经历展开。',('She is writing a biography of a nineteenth-century explorer.','她正在写一位十九世纪探险家的传记。'),('The biography draws on letters and family records.','这部传记使用了书信和家族档案。'),sources=['https://www.etymonline.com/word/biography','https://en.wiktionary.org/wiki/biography']),
E('biographical','英 /ˌbaɪəˈɡræfɪkəl/；美 /ˌbaɪəˈɡræfɪkəl/','传记的；有关某人生平的','这段材料告诉你：这个人是谁，经历过什么，人生怎样走到这里。','biography 的词干与 -ical 构成形容词；英语记录中 biographical 早于较短的 biographic。',H(BG,'英语 biography → biographical','传记、生平 → 有关生平的'),'biographical details 可以是出生、教育、工作等信息，不一定已经连成一本完整传记。a biographical film 以真实人物的生平为基础，但电影仍可能压缩或改编事件。','biographical details；a biographical note；a biographical film。','biographical 是关于人生经历的；biological 是关于生命、生物的。只差几个字母，讨论的层面就不同。',('Please include a short biographical note.','请附上一段简短的个人生平介绍。'),('The archive contains valuable biographical details.','档案中保存了宝贵的生平资料。'),sources=['https://www.etymonline.com/word/biographical','https://dictionary.cambridge.org/dictionary/english/biographical']),
E('biographic','/ˌbaɪəˈɡræfɪk/','传记的；有关生平的','说的仍是一个人的人生资料，只是用了较短的形容词形式。','与 biography 同族的 -ic 形式；不能因为 biographic 较短，就把它硬排成 biographical 的历史前身。',H(BG,'英语传记词族 → biographic','有关传记、生平资料的'),'biographic 和 biographical 通常意义相近。biographic data 在表格、档案等语境中可指姓名、出生信息等个人资料；具体包括哪些项目，由使用场景决定。普通叙述中 biographical 更常见。','biographic data；biographic information；biographic research。','biographic data 是人生、身份资料；biometric data 是指纹、面部等用于测量或识别的生物特征数据。',('The form asks for basic biographic data.','表格要求填写基本个人资料。'),('The researcher checked the biographic information against the archive.','研究者把生平信息与档案进行了核对。'),sources=['https://www.etymonline.com/word/biographical','https://www.merriam-webster.com/dictionary/biographic']),
E('biographer','英 /baɪˈɒɡrəfə/；美 /baɪˈɑːɡrəfər/','传记作者','替一个人的一生找材料、理线索、写出叙述的人。','biography 对应的人称形式 -er；不是生物学家，也不是只负责拍照的人。',H(BG,'英语 biography → biographer','生平记述 → 写传记的人'),'biographer 要面对资料之间的矛盾、人物自己的说法和旁人的记忆。一个好的生平解释需要证据，不能只把人物的话全部当成事实。这里 bio- 对应的是“一生”，不是实验室里的生物学。','the poet’s biographer；an official biographer；a biographer of。','biographer 写别人的生平；autobiographer 写自己的生平；biologist 研究生物。',('Her biographer interviewed colleagues and relatives.','她的传记作者采访了同事和亲属。'),('The biographer found a letter that changed his account of the event.','传记作者发现一封信，改变了他对那件事的叙述。'),sources=['https://www.etymonline.com/word/biographer','https://www.merriam-webster.com/dictionary/biographer']),
E('biographically','/ˌbaɪəˈɡræfɪkli/','从生平角度；就个人经历而言','理解一段文字时，先回头看看作者当时过着怎样的生活。','biographical + -ly，说明采用生平研究的角度或方式。',H(BG,'英语 biographical → biographically','有关生平的 → 从生平角度'),'read a poem biographically 是结合诗人的人生经历来解读，而不是自动认为诗中的“我”就是作者本人。这个副词强调解释角度，不能替代逐项核实的证据。','read biographically；interpret biographically；biographically significant。','biographically 是从人生经历出发；historically 是从历史背景出发。两种角度可以结合，范围并不完全一样。',('The critic reads the poem biographically.','评论者结合诗人的生平来解读这首诗。'),('The year was biographically significant because it marked her return home.','从她的生平看，那一年很重要，因为她在那年回到了家乡。'),sources=['https://www.etymonline.com/word/biographical','https://en.wiktionary.org/wiki/biographically']),
E('biopic','英 /ˈbaɪəʊpɪk/；美 /ˈbaɪoʊpɪk/','传记电影','把一个真实人物的人生故事搬上银幕。','biographical picture 的缩合；bio 对应传记，pic 是 picture“电影、影片”的缩写。',BG+[['英语 biographical picture → bio + pic → biopic','传记影片 → 缩短为一个词']],'a biopic about a musician 通常讲一位音乐家的真实人生，同时可能通过演员表演和情节改编来呈现。它不是必须采用访谈、档案镜头的纪录片。按 bio + pic 记读音最直观，不要误拆成 bi + opic。','a biopic about；star in a biopic；a musical biopic。','biopic 强调真实人物的生平题材；documentary 强调纪录片形式。某部作品可能同时符合两者。',('She plays the scientist in a new biopic.','她在一部新的传记电影中饰演那位科学家。'),('The biopic focuses on the singer’s early career.','这部传记电影聚焦于歌手的早期事业。'),sources=['https://www.etymonline.com/word/biopic','https://dictionary.cambridge.org/dictionary/english/biopic']),
E('biochemistry','英 /ˌbaɪəʊˈkemɪstri/；美 /ˌbaɪoʊˈkemɪstri/','生物化学','把镜头推近到细胞里面，看分子怎样让生命运转。','bio-“生物、生命” + chemistry“化学”，英语中用已有构词材料组成学科名称。',BC,'消化食物、释放能量、复制遗传信息，都涉及分子和化学反应。biochemistry 就研究生命中的这些化学过程。它不是把 biology 和 chemistry 两本课本简单叠起来，而是用化学层面的证据解释生物怎样工作。','study biochemistry；a degree in biochemistry；the biochemistry of metabolism。','biology 范围更广，能研究生态、演化等；biochemistry 尤其关注生命的分子结构与化学过程。',('She studies the biochemistry of energy production in cells.','她研究细胞产生能量的生物化学过程。'),('Biochemistry helps explain how enzymes work.','生物化学帮助解释酶怎样工作。'),sources=['https://www.etymonline.com/word/biochemistry','https://www.biochemistry.org/careers-and-education/studying-biochemistry/']),
E('biochemical','英 /ˌbaɪəʊˈkemɪkəl/；美 /ˌbaɪoʊˈkemɪkəl/','生物化学的；生物化学物质','说的是生命活动中分子之间发生的事情。','bio- + chemical；与 biochemistry 对应，但形容词可直接按这两个成分理解。',B+[['英语 bio- + chemical → biochemical','生命、生物 + 化学的 → 生物化学的']],'a biochemical reaction 是生物系统中的化学反应；a biochemical pathway 则是一串相互衔接的反应步骤。作名词时 a biochemical 指与生命过程相关的化学物质，不等于天然无害。','a biochemical reaction；a biochemical pathway；biochemical analysis。','biochemical 指研究层面或过程性质；biodegradable 指能经生物作用分解。两者不能互换。',('The enzyme speeds up a biochemical reaction.','这种酶加快了一个生物化学反应。'),('The team studied biochemical changes in the cells.','团队研究了细胞中的生物化学变化。'),sources=['https://en.wiktionary.org/wiki/biochemical','https://www.acs.org/careers/chemical-sciences/areas/biochemistry.html']),
E('biochemist','英 /ˌbaɪəʊˈkemɪst/；美 /ˌbaɪoʊˈkemɪst/','生物化学家','想知道一个细胞为什么这样工作，就去查里面的分子和反应。','与 biochemistry 对应的职业名词；可理解为 bio- + chemist，也有从 biochemistry 逆构的分析。',BC+[['英语 biochemistry 词族 → biochemist','生物化学 → 研究生物化学的人']],'biochemist 可能研究蛋白质、酶、代谢或细胞信号。研究对象虽然是生命，问题常落在具体分子如何结合、变化和发挥作用。这个职业并不自动意味着有临床诊疗资格。','a research biochemist；work as a biochemist；a team of biochemists。','biochemist 研究生命化学；pharmacist 通常指药师，工作和资格要求不同。',('The biochemist tested how the protein binds to another molecule.','生物化学家测试了这种蛋白质如何与另一种分子结合。'),('A biochemist joined the project to study the enzyme.','一位生物化学家加入项目，研究这种酶。'),sources=['https://www.etymonline.com/word/biochemist','https://en.wiktionary.org/wiki/biochemist','https://www.acs.org/careers/chemical-sciences/areas/biochemistry.html']),
E('biochem','英 /ˈbaɪəʊkem/；美 /ˈbaɪoʊkem/','生物化学〔口语简称〕','课表或聊天里，把很长的 biochemistry 缩成一个顺口的短词。','biochemistry 的截短形式；也可从 bio + chem 看出原来的两个部分。',H(BC,'英语 biochemistry → biochem','生物化学 → 课堂、聊天等场合的简称'),'I have biochem tomorrow 常说“我明天有生化课”。它也可以泛指生化学科或相关领域，具体看语境。正式课程名、论文题目中通常写完整的 biochemistry 更清楚。','a biochem class；a biochem major；study biochem。','biochem 是简称，不是另一个独立学科；biotech 通常简称 biotechnology“生物技术”。',('I have a biochem exam on Friday.','我星期五有生化考试。'),('She switched from physics to biochem.','她从物理转到了生物化学专业。'),sources=['https://en.wiktionary.org/wiki/biochem','https://www.merriam-webster.com/dictionary/biochem']),
]
